-- Read-only, permission-gated payload for an administrator to prepare a group message.
-- Apply as a new migration generated by the Supabase CLI, after testing in an isolated database.
create or replace function public.admin_get_marketplace_job_whatsapp_payload(
  target_project_id uuid, target_job_id uuid
) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='42501'; end if;
  perform app_private.require_project_permission(target_project_id,'marketplace.manage');
  select jsonb_build_object(
    'serviceCode',j.service_code,
    'origin',sr.origin_text,'destination',sr.destination_text,
    'vehicleCategory',coalesce(sr.vehicle_category_code,j.pricing_vehicle_category_code),
    'price',j.final_price,'currency',j.currency,
    'scheduledFor',sr.scheduled_for,
    'distanceKm',case when sr.details->>'estimated_distance_km' ~ '^[0-9]+(\.[0-9]+)?$'
      then (sr.details->>'estimated_distance_km')::numeric end,
    'paymentMethod',case when sr.details->>'ride_payment_method' in ('cash','transfer')
      then sr.details->>'ride_payment_method' end,
    'passengers',sr.passenger_count,
    'weightKg',sr.cargo_weight_kg,'volumeM3',sr.cargo_volume_m3,
    'lengthCm',sr.cargo_length_cm,'widthCm',sr.cargo_width_cm,'heightCm',sr.cargo_height_cm,
    'bodyType',sr.required_body_type,
    'loadHelp',sr.details->'load_help','unloadHelp',sr.details->'unload_help',
    'urgent',sr.details->'urgent',
    'stopCount',case when sr.details->>'stop_count' ~ '^[0-9]+$'
      then (sr.details->>'stop_count')::numeric end,
    'comment',case when j.service_code in ('cargo','courier')
      and app_private.has_project_permission(target_project_id,'customers.view') then sr.notes end
  ) into result
  from public.jobs j
  join public.service_requests sr on sr.project_id=j.project_id and sr.id=j.service_request_id
  where j.project_id=target_project_id and j.id=target_job_id
    and j.status='published' and j.expires_at>now()
    and not j.is_test and j.test_deleted_at is null
    and j.assigned_driver_user_id is null and j.assigned_vehicle_id is null
    and not exists(select 1 from public.job_assignments a where a.project_id=j.project_id and a.job_id=j.id)
    and not exists(
      select 1 from app_private.marketplace_driver_promo_attribution a
      join app_private.marketplace_driver_promo_settings s on s.project_id=a.project_id
        and s.profiles_enabled and s.priority_enabled
      where a.project_id=j.project_id and a.job_id=j.id
        and a.phase='preferred' and a.priority_until>now()
    );
  if result is null then raise exception 'JOB_NOT_SHAREABLE' using errcode='22023'; end if;
  return result;
end;
$$;
revoke all on function public.admin_get_marketplace_job_whatsapp_payload(uuid,uuid) from public,anon,authenticated;
grant execute on function public.admin_get_marketplace_job_whatsapp_payload(uuid,uuid) to authenticated;
